from pathlib import Path
import difflib,subprocess,hashlib,json
R=Path.cwd();A=R/'artifacts/crow-v15-spanwise-flow-audit-20261112';B=R/'build/crow-v15-spanwise-flow-audit-20261112';source=R/'build/crow-v15-wing-aero-alignment-20261110/FlappingWingDynamics.metal'
s=source.read_text();old="            const float3 incomingAir =\n                dispatch.windVelocityAndDensity.xyz - pointVelocity;\n            const float speedSquared = dot(incomingAir, incomingAir);";new="            const float3 fullIncomingAir =\n                dispatch.windVelocityAndDensity.xyz - pointVelocity;\n            const float3 incomingAir = fullIncomingAir - span * dot(fullIncomingAir, span);\n            const float speedSquared = dot(incomingAir, incomingAir);";assert s.count(old)==1;t=s.replace(old,new);(A/'sectional-flow.patch').write_text(''.join(difflib.unified_diff(s.splitlines(True),t.splitlines(True),fromfile='a/current-aero.metal',tofile='b/sectional-flow-diagnostic.metal')));(B/'sectional.metal').write_text(t)
subprocess.run(['xcrun','-sdk','macosx','metal','-std=metal4.0','-O3','-fno-fast-math','-I',str(R/'include'),'-c',str(B/'sectional.metal'),'-o',str(B/'sectional.air')],check=True)
airs=[str(x) for x in (R/'build/shaders').glob('MetalRobo*.air') if x.name not in ('MetalRoboFlappingWingDynamics.air','MetalRoboLocomotionTask.air')];airs.extend([str(B/'sectional.air'),str(R/'build/crow-v15-toe-flight-screen-20261110/tracking.air')]);subprocess.run(['xcrun','-sdk','macosx','metallib',*airs,'-o',str(B/'sectional.metallib')],check=True)
h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();(A/'hashes.json').write_text(json.dumps({'current_source':h(source),'diagnostic_source':h(B/'sectional.metal'),'diagnostic_air':h(B/'sectional.air'),'diagnostic_metallib':h(B/'sectional.metallib'),'current_metallib':h(R/'build/crow-v15-wing-steering-without-body-moments-20261112/baseline.metallib'),'evaluator':h(R/'build/crow-v15-aero-yaw-sensitivity-20261112/evaluate'),'host':h(R/'build/crow-v15-toe-velocity-substep-observer-20261111/libmetalrobo.dylib')},indent=2)+'\n')
